def fill_component_interior(component):
    """Fill the bounding box interior between leftmost and rightmost markers in each row"""
    filled = []
    for (r, c) in component:
        filled.append((r, c))

    # Find bounding box of component
    if not filled:
        return filled

    min_r, max_r = min(r for r,c in filled), max(r for r,c in filled)
    min_c, max_c = min(c for r,c in filled), max(c for r,c in filled)

    # Fill rows of component with cells between min_c and max_c
