def fill_group(group):
    if not group:
        return set()

    cells = set(group)
    min_r, max_r = min(r for r,c in group), max(r for r,c in group)
    min_c, max_c = min(c for r,c in group), max(c for r,c in group)

    for r in range(min_r, max_r + 1):
        for c in range(min_c, max_c + 1):
            cells.add((r, c))

    # Return cells - 1 from group as fill
    original = set(group)
    fill_cells = cells - original
    return fill_cells

